    { id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", level = 52, minLevel = 48, faction = "Horde", finish = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, objective = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.  " },
