    { id = 4735, name = "Egg Collection", level = 60, minLevel = 57, requires = { 4734 }, giver = "Tinkee Steamboil", start = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, objective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes." },
    { id = 4742, name = "Seal of Ascension (1/2)", level = 60, minLevel = 57, giver = "Vaelan", start = { npc = "Vaelan" }, finish = { npc = "Vaelan" }, objective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.  The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe." },
    { id = 4743, name = "Seal of Ascension (2/2)", level = 60, minLevel = 57, requires = { 4742 }, giver = "Vaelan", start = { npc = "Vaelan" }, finish = { npc = "Vaelan" }, objective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.  It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!" },
