    { id = 4862, name = "En-Ay-Es-Tee-Why", level = 59, minLevel = 55, giver = "Kibler", start = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, finish = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, objective = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.  By the sound of it, these eggs could be found near spiders. " },
