    { id = 4903, name = "Warlord's Command", level = 60, minLevel = 55, faction = "Horde", giver = "Warlord Goretooth", start = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, finish = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." },
