    { id = 4974, name = "For The Horde!", level = 60, minLevel = 55, requires = { 4941 }, faction = "Horde", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, finish = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." },
