    { id = 5047, name = "Finkle Einhorn, At Your Service!", level = 60, minLevel = 55, giver = "Finkle Einhorn", start = { npc = "Finkle Einhorn" }, finish = { npc = "Malyfous Darkhammer", area = 618, x = 61.0, y = 38.8 }, objective = "Talk to Malyfous Darkhammer in Everlook." },
    { id = 5063, name = "Cap of the Scarlet Savant", level = 60, minLevel = 57, requires = { 5047 }, finish = { npc = "Malyfous Darkhammer", area = 618, x = 61.0, y = 38.8 }, objective = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.   You will also be required to pay 50 gold pieces for the crafting of the item." }, -- cadena
    { id = 5065, name = "The Lost Tablets of Mosh'aru", level = 58, minLevel = 40, requires = { 3528 }, giver = "Prospector Ironboot", start = { npc = "Prospector Ironboot", area = 440, x = 66.9, y = 24.0 }, finish = { npc = "Prospector Ironboot", area = 440, x = 66.9, y = 24.0 }, objective = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris." }, -- cadena
