    { id = 5081, name = "Maxwell's Mission", level = 60, minLevel = 55, requires = { 5002 }, faction = "Alliance", giver = "Marshal Maxwell", start = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, finish = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, objective = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done." },
    { id = 5089, name = "General Drakkisath's Command", level = 60, minLevel = 55, faction = "Alliance", finish = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, objective = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes." },
    { id = 5102, name = "General Drakkisath's Demise", level = 60, minLevel = 55, requires = { 5089 }, faction = "Alliance", giver = "Marshal Maxwell", start = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, finish = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, objective = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done. " },
    { id = 5126, name = "Lorax's Tale", level = 60, minLevel = 55, giver = "Lorax", start = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, finish = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, objective = "Speak with Lorax. Listen to what he has to say. " }, -- cadena
    { id = 5127, name = "The Demon Forge", level = 60, minLevel = 55, requires = { 5126 }, giver = "Lorax", start = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, finish = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring." },
    { id = 5160, name = "The Matron Protectorate", level = 60, minLevel = 57, giver = "Awbee", start = { npc = "Awbee" }, finish = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale." },
    { id = 5161, name = "Wrath of the Blue Flight (1/2)", level = 60, minLevel = 57, requires = { 5160 }, giver = "Haleh", start = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, finish = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, objective = "Speak with Haleh if you wish to continue." }, -- cadena
