    { id = 5164, name = "Catalogue of the Wayward", level = 60, minLevel = 57, requires = { 5162 }, giver = "Jeziba", start = { npc = "Jeziba", area = 28, x = 39.4, y = 66.8 }, objective = "Read from the Catalogue of the Wayward. " }, -- cadena
    { id = 5522, name = "Leonid Barthalomew", level = 60, minLevel = 57, requires = { 4735 }, giver = "Tinkee Steamboil", start = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, finish = { npc = "Leonid Barthalomew the Revered", area = 139, x = 81.7, y = 57.8 }, objective = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands." }, -- cadena
    { id = 6402, name = "Stormwind Rendezvous", level = 60, minLevel = 50, requires = { 4322 }, faction = "Alliance", giver = "Marshal Maxwell", start = { npc = "Marshal Maxwell", area = 46, x = 84.7, y = 69.0 }, finish = { npc = "Reginald Windsor" }, objective = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived." }, -- cadena
    { id = 6403, name = "The Great Masquerade", level = 60, minLevel = 50, requires = { 6402 }, faction = "Alliance", giver = "Reginald Windsor", start = { npc = "Reginald Windsor" }, finish = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 78.2, y = 18.0 }, objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!" }, -- cadena
    { id = 6501, name = "The Dragon's Eye", level = 60, minLevel = 50, requires = { 6403 }, faction = "Alliance", giver = "Highlord Bolvar Fordragon", start = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 78.2, y = 18.0 }, finish = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." }, -- cadena
    { id = 6502, name = "Drakefire Amulet", level = 60, minLevel = 50, requires = { 6501 }, faction = "Alliance", giver = "Haleh", start = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, finish = { npc = "Haleh", area = 618, x = 54.5, y = 51.2 }, objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire." },
    { id = 6566, name = "What the Wind Carries", level = 60, minLevel = 55, requires = { 4974 }, faction = "Horde", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, finish = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, objective = "Listen to Thrall." }, -- cadena
    { id = 6567, name = "The Champion of the Horde", level = 60, minLevel = 55, requires = { 6566 }, faction = "Horde", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, finish = { npc = "Rexxar", area = 357, x = 46.4, y = 18.2 }, objective = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas." }, -- cadena
    { id = 6568, name = "The Testament of Rexxar", level = 60, minLevel = 55, requires = { 6567 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 357, x = 46.4, y = 18.2 }, finish = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.8 }, objective = "Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands." }, -- cadena
    { id = 6569, name = "Oculus Illusions", level = 60, minLevel = 55, requires = { 6568 }, faction = "Horde", giver = "Myranda the Hag", start = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.8 }, finish = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.8 }, objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete." },
    { id = 6570, name = "Emberstrife", level = 60, minLevel = 55, requires = { 6569 }, faction = "Horde", giver = "Myranda the Hag", start = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.8 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife. " }, -- cadena
    { id = 6582, name = "The Test of Skulls, Scryer", level = 60, minLevel = 55, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring." }, -- cadena
    { id = 6583, name = "The Test of Skulls, Somnus", level = 60, minLevel = 55, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." }, -- cadena
    { id = 6584, name = "The Test of Skulls, Chronalis", level = 60, minLevel = 55, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife." }, -- cadena
    { id = 6585, name = "The Test of Skulls, Axtroz", level = 60, minLevel = 55, requires = { 6582, 6583, 6584 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." }, -- cadena
    { id = 6601, name = "Ascension...", level = 60, minLevel = 55, requires = { 6585 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Rexxar", area = 357, x = 46.4, y = 18.2 }, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." }, -- cadena
    { id = 6602, name = "Blood of the Black Dragon Champion", level = 60, minLevel = 55, requires = { 6601 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 357, x = 46.4, y = 18.2 }, finish = { npc = "Rexxar", area = 357, x = 46.4, y = 18.2 }, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar." },
    { id = 7761, name = "Blackhand's Command", level = 60, minLevel = 55, objective = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.  The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate." },
