ns.AddQuests("dm", {
    { id = 1193, name = "A Broken Trap", level = 60, minLevel = 56 },
    { id = 1318, name = "Unfinished Gordok Business (1/2)", level = 60, minLevel = 56, objective = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." },
    { id = 5518, name = "The Gordok Ogre Suit (1/2)", level = 60, minLevel = 56, giver = "Knot Thimblejack", start = { npc = "Knot Thimblejack" }, finish = { npc = "Knot Thimblejack" }, objective = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul." },
    { id = 5519, name = "The Gordok Ogre Suit (2/2)", level = 60, minLevel = 56, requires = { 5518 }, giver = "Knot Thimblejack", start = { npc = "Knot Thimblejack" }, finish = { npc = "Knot Thimblejack" } },
