    { id = 5528, name = "The Gordok Taste Test", level = 60, minLevel = 57, giver = "Stomper Kreeg", start = { npc = "Stomper Kreeg" }, finish = { npc = "Stomper Kreeg" } },
    { id = 7429, name = "Free Knot! (2/2)", level = 60, minLevel = 57, requires = { 5525 }, giver = "Knot Thimblejack", start = { npc = "Knot Thimblejack" }, finish = { npc = "Knot Thimblejack" } },
    { id = 7441, name = "Pusillin and the Elder Azj'Tordin", level = 58, minLevel = 54, giver = "Azj'Tordin", start = { npc = "Azj'Tordin", area = 357, x = 76.9, y = 37.4 }, finish = { npc = "Azj'Tordin", area = 357, x = 76.9, y = 37.4 }, objective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations." },
    { id = 7461, name = "The Madness Within", level = 60, minLevel = 56, giver = "Shen'dralar Ancient", start = { npc = "Shen'dralar Ancient" }, finish = { npc = "Shen'dralar Ancient" }, objective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete this quest." },
    { id = 7462, name = "The Treasure of the Shen'dralar", level = 60, minLevel = 56, requires = { 7461 }, faction = "Alliance", giver = "Shen'dralar Ancient", start = { npc = "Shen'dralar Ancient" }, objective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!" },
    { id = 7463, name = "Arcane Refreshment", level = 60, minLevel = 60, giver = "Lorekeeper Lydros", start = { npc = "Lorekeeper Lydros" }, finish = { npc = "Lorekeeper Lydros" }, objective = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence." },
    { id = 7481, name = "Elven Legends", level = 60, minLevel = 54, faction = "Horde", giver = "Sage Korolusk", start = { npc = "Sage Korolusk", area = 357, x = 75.2, y = 43.8 }, finish = { npc = "Sage Korolusk", area = 357, x = 75.2, y = 43.8 }, objective = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find." },
    { id = 7482, name = "Elven Legends", level = 60, minLevel = 54, faction = "Alliance", giver = "Scholar Runethorn", start = { npc = "Scholar Runethorn", area = 357, x = 31.6, y = 43.5 }, finish = { npc = "Scholar Runethorn", area = 357, x = 31.6, y = 43.5 }, objective = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find." },
    { id = 7483, name = "Libram of Rapidity", level = 60, minLevel = 58, giver = "Lorekeeper Lydros", start = { npc = "Lorekeeper Lydros" }, finish = { npc = "Lorekeeper Lydros" }, objective = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity." },
    { id = 7484, name = "Libram of Focus", level = 60, minLevel = 58, giver = "Lorekeeper Lydros", start = { npc = "Lorekeeper Lydros" }, finish = { npc = "Lorekeeper Lydros" }, objective = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus." },
