    { id = 5465, name = "Soulbound Keepsake", level = 60, minLevel = 57, requires = { 5464 }, giver = "Leonid Barthalomew the Revered", start = { npc = "Leonid Barthalomew the Revered", area = 139, x = 81.7, y = 57.8 }, finish = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake." }, -- cadena
