    { id = 5742, name = "Redemption", level = 56, minLevel = 52, requires = { 5542, 5543, 5544 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.7 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.7 }, objective = "Listen to what Tirion Fordring has to say." }, -- cadena
