    { id = 5846, name = "Of Love and Family (1/2)", level = 58, minLevel = 52, requires = { 5845 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.7 }, finish = { npc = "Artist Renfray", area = 28, x = 65.8, y = 75.4 }, objective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." }, -- cadena
