    { id = 5861, name = "Find Myranda", level = 60, minLevel = 52, requires = { 5848 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.7 }, finish = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.8 }, objective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift." }, -- cadena
